// /api/md is the surface every /docs/* page and the site root reach through
// content negotiation, so it is where a missing frontmatter block costs the
// most: an agent that fetched the Markdown had no machine-readable title and no
// statement of which URL the body belongs to.
//
// Kept out of markdown-routes.test.ts because this route imports @/lib/source
// (the generated fumadocs MDX index, un-transformable under vitest), so the
// whole file has to run with that module mocked.

import { describe, expect, it, vi } from "vitest";

vi.mock("@/lib/source", () => ({
	source: {
		getPages: () => [
			{
				url: "/docs/foundations/overview",
				data: { title: "Overview", description: "Start here." },
			},
		],
		getPage: (slug?: string[]) =>
			slug?.join("/") === "foundations/overview"
				? {
						slugs: ["foundations", "overview"],
						data: {
							// A colon and a quote, because both would break a naive
							// unquoted YAML scalar and turn the page into a parse error.
							title: 'Overview: the "map" page',
							description: "Start here.",
						},
					}
				: undefined,
	},
}));

vi.mock("@/lib/docs-content", () => ({
	readDocBody: async () => "Body text.",
}));

import { GET } from "@/app/api/md/[[...slug]]/route";
import { PAGE_SUMMARY, SITE } from "@/lib/constants";

async function get(slug?: string[]): Promise<Response> {
	return await GET(new Request("https://orchestkit.yonyon.ai/api/md"), {
		params: Promise.resolve({ slug }),
	});
}

function frontmatter(md: string): Record<string, string> {
	expect(md.startsWith("---\n")).toBe(true);
	const end = md.indexOf("\n---\n", 3);
	expect(end).toBeGreaterThan(0);
	const out: Record<string, string> = {};
	for (const line of md.slice(4, end).split("\n")) {
		const at = line.indexOf(": ");
		if (at !== -1) out[line.slice(0, at)] = JSON.parse(line.slice(at + 2));
	}
	return out;
}

describe("/api/md frontmatter", () => {
	it("the site root names its title, description and canonical", async () => {
		const md = await (await get()).text();
		expect(frontmatter(md)).toEqual({
			title: SITE.name,
			// The root layout's metadata.description, which IS the homepage's
			// description because the homepage sets no override.
			description: PAGE_SUMMARY.site,
			canonical: SITE.domain,
		});
	});

	it("a docs page's frontmatter is that page's own metadata", async () => {
		const md = await (await get(["foundations", "overview"])).text();
		expect(frontmatter(md)).toEqual({
			title: 'Overview: the "map" page',
			description: "Start here.",
			canonical: `${SITE.domain}/docs/foundations/overview`,
		});
	});

	it("a title carrying a colon and quotes still parses as one block", async () => {
		const md = await (await get(["foundations", "overview"])).text();
		// Exactly two delimiters: a mis-escaped title would open a third.
		expect(md.split("\n").filter((l) => l === "---")).toHaveLength(2);
		expect(md).toContain('title: "Overview: the \\"map\\" page"');
	});

	it("the body still follows, unchanged, after the block", async () => {
		const md = await (await get(["foundations", "overview"])).text();
		expect(md).toContain('# Overview: the "map" page');
		expect(md).toContain("Body text.");
	});

	it("a miss gets no frontmatter, because canonical would have to be invented", async () => {
		const res = await get(["nope"]);
		expect(res.status).toBe(404);
		expect(await res.text()).not.toContain("---");
	});

	it("Vary keys on Accept AND User-Agent, the two inputs that pick the body", async () => {
		const res = await get();
		expect(res.headers.get("Vary")).toBe("Accept, Accept-Encoding, User-Agent");
	});
});
